sketch:
// 由装配台按当前接线自动生成 —— 早期原型，简化仿真
// 板子：Raspberry Pi Pico（U1）  Arduino 板子包：rp2040:rp2040（arduino-pico 板子包）
// 接线：
//   GP14 ← SW1（另一端接 GND，用内部上拉）
//   GP15 → R1 → D1 阳极
//   GP16 → M1 信号线（橙）
//   GP26 ← RV1 滑片（两端 3V3 / GND）
#include <Servo.h>

const int LED_PIN = 15;
const int BTN_PIN = 14;
const int POT_PIN = 26;
const int SERVO_PIN = 16;
Servo servo1;

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BTN_PIN, INPUT_PULLUP);
  servo1.attach(SERVO_PIN);
  Serial.println("ready");
}

void loop() {
  if (digitalRead(BTN_PIN) == LOW) {
    digitalWrite(LED_PIN, HIGH);
  } else {
    digitalWrite(LED_PIN, LOW);
  }
  int raw = analogRead(POT_PIN);
  servo1.write(map(raw, 0, 1023, 0, 180));
  Serial.print("pot=");
  Serial.println(raw);
  delay(50);
}
